create unique index if not exists recovery_events_checkout_type_unique on public.recovery_events (checkout_id,event_type); create or replace function public.enqueue_checkout_recovery_events(p_limit integer default 100) returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin with candidates as (select id,user_id from public.checkout_sessions where status='abandoned' and recovery_status in ('pending','queued') and (recovery_next_at is null or recovery_next_at<=now()) and recovery_count<5 order by abandoned_at asc nulls first limit greatest(1,least(p_limit,1000))) insert into public.recovery_events(user_id,checkout_id,event_type,status,payload) select c.user_id,c.id,'recovery_due','queued',jsonb_build_object('checkout_id',c.id) from candidates c on conflict (checkout_id,event_type) do nothing; get diagnostics n=row_count; update public.checkout_sessions s set recovery_status='queued',recovery_next_at=now()+interval '1 hour' where s.id in (select checkout_id from public.recovery_events where status='queued' and event_type='recovery_due') and s.recovery_status in ('pending','queued'); return n; end; $$; revoke execute on function public.enqueue_checkout_recovery_events(integer) from public,anon,authenticated; grant execute on function public.enqueue_checkout_recovery_events(integer) to service_role;